```vue
<template>
 <view class="xinyi-content">
 <NavBar title="实时推演" leftIcon="undo-filled" right-text="退出登录" :user="user"></NavBar>

 <view class="create-new" v-if="isAdmin">
 <button class="create-new-button" @click="createOne">创建新的推演</button>
 <button class="create-new-button2" @click="toEdit">查看想定</button>
 </view>

 <view class="product-list__view">
 <view
 class="product-item"
 v-for="(item, index) in verdictRecordList"
 :key="index"
 @click="nativeTo(item)"
 >
 <uni-card class="u-card" spacing="0" padding="20px" margin="10px">
 <view class="card-content" @click="showModal(item)">
 <view class="card-header">
 <view class="status-badge" :class="item.status === 10 ? 'status-waiting' : 'status-running'">
 {{ item.status === 10 ? "未开始" : "进行中" }}
 </view>
 <view class="room-code">房间号：{{ item.inviteCode }}</view>
 </view>

 <view class="players-info">
 <view class="player-item red-camp">
 <view class="camp-label">{{ item.firstCampName || '红方' }}</view>
 <view class="player-name" v-if="item.firstUserName">
 <text class="icon"></text>
 {{ item.firstUserName }}
 </view>
 <view class="player-waiting" v-else>
 <text class="icon">⏳</text>
 等待加入
 </view>
 </view>

 <view class="vs-divider">VS</view>

 <view class="player-item blue-camp">
 <view class="camp-label">{{ item.secondCampName || '蓝方' }}</view>
 <view class="player-name" v-if="item.secondUserName">
 <text class="icon"></text>
 {{ item.secondUserName }}
 </view>
 <view class="player-waiting" v-else>
 <text class="icon">⏳</text>
 等待加入
 </view>
 </view>
 </view>

 <view class="card-footer">
 <view class="create-time">
 <text class="time-icon"></text>
 {{ formatTime(item.createTime) }}
 </view>
 </view>
 </view>
 </uni-card>
 </view>
 </view>

 <uni-pagination
 class="page"
 :total="total"
 :current="queryParams.pageNum"
 @change="pageChange"
 :pageSize="queryParams.pageSize"
 ></uni-pagination>

 <NjustPopup ref="isModalVisible">
 <view class="product-item__btn" v-if="!isAdmin">
 <button class="run__btn" v-if="currentItem.status === 10 &&
 (user.id === currentItem.firstUserId || user.id === currentItem.secondUserId)"
 @click="toRoom('3',currentItem)">进入房间</button>
 <button class="init__btn" v-else-if="currentItem.status === 10" @click="toRoom('0',currentItem)">组队</button>
 <button class="run__btn" v-else-if="currentItem.status !== 10 &&
 (user.id === currentItem.firstUserId || user.id === currentItem.secondUserId)"
 @click="toRoom('1',currentItem)">进入战场</button>
 <button class="watch__btn" v-else-if="currentItem.status !== 10" @click="toRoom('2',currentItem)">观战</button>
 </view>
 <view style="height: 30px"></view>
 </NjustPopup>

 <NjustPopup ref="camp">
 <uni-data-select class="njust-select" v-model="campId" :localdata="campList"></uni-data-select>
 <button class="njust-button" @click="chooseCamp()">进入房间</button>
 <view style="height: 30px"></view>
 </NjustPopup>
 </view>
</template>
```
</augment_code_snippet>

