 197	 this.campList = res.data.data;
 198	 this.campList.forEach((item) => {
 199	 item.text = item.name;
 200	 item.value = item.id;
 201	 });
 202	 this.$refs.camp.open();
 203	 })
 204	 .catch((err) => {});
 205	 break;
 206	 case '1' :
 207	 uni.navigateTo({
 208	 url:
 209	 '/pages/wargame/index-v2?verdictRecordId=' +
 210	 this.currRecordId +
 211	 '&isUser=' +
 212	 !this.isAdmin +
 213	 '&campId=' +
 214	 itemCampId
 215	 });
 216	 break;
 217	 case '2' :
 218	 sendMsg(JSON.stringify({ action: 'watchJoinRoom', verdictRecordId: this.currRecordId }));
 219	 uni.navigateTo({
 220	 url: '/pages/wargame/index-v2?verdictRecordId=' + this.currRecordId + '&type=watch'
 221	 });
 222	 break;
 223	 case '3' :
 224	 uni.navigateTo({
 225	 url:
 226	 '/pages/room/create?inviteCode=' +
 227	 this.inviteCode +
 228	 '&verdictRecordId=' +
 229	 this.currRecordId +
 230	 '&campId=' +
 231	 itemCampId
 232	 });
 233	 }
 234	 },
 235	 chooseCamp() {
 236	 if(this.campId === ''){
 237	 uni.showToast({
 238	 title: '请选择阵营',
 239	 icon: 'none'
 240	 })
 241	 return;
 242	 }
 243	 chooseCamp({ id: this.campId, verdictRecordId: this.currRecordId, userType: this.userType })
 244	 .then((res) => {
 245	 console.log(res)
 246	 if (res.data.code === 200) {
 247	 uni.navigateTo({
 248	 url:
 249	 '/pages/room/create?inviteCode=' +
 250	 this.inviteCode +
 251	 '&verdictRecordId=' +
 252	 this.currRecordId +
 253	 '&campId=' +
 254	 this.campId
 255	 });
 256	 }
 257	 else {
 258	 uni.showToast({
 259	 title: res.data.msg,
 260	 icon: 'none'
 261	 })
 262	 }
 263	 })
 264	 .catch((err) => {});
 265	 },
 266	 }
 267	};
