=\"item in judgeOptions\" :key=\"item.value\" class=\"radio-item\">\n <radio :value=\"item.value\" v-model=\"judgeResult\" />\n <text>{{ item.label }}</text>\n </label>\n </view>\n </view>\n </view>\n </view>\n \n <view class=\"panel-footer\">\n <button class=\"sci-fi-button primary\" @click=\"confirmJudge\">\u786e\u8ba4</button>\n <button class=\"sci-fi-button secondary\" @click=\"closeJudge\">\u5173\u95ed</button>\n </view>\n </view>\n </uni-popup>\n\n <!-- \u8bc4\u5206\u5f39\u7a97 -->\n <uni-popup ref=\"scorePopup\" :mask-click=\"false\">\n <view class=\"sci-fi-panel score-modal\">\n <view class=\"panel-header\">\n <view class=\"panel-title\">\u8bf7\u8f93\u5165\u8bc4\u5206\u7ed3\u679c</view>\n </view>\n \n <view class=\"panel-content\">\n <view class=\"action-info\">\n <view class=\"info-row\">\n <text class=\"label\">\u90e8\u961f\u884c\u52a8\uff1a</text>\n <text class=\"value\">{{ actionInfo.actionDesc }}</text>\n </view>\n </view>\n \n <view class=\"score-input\">\n <text class=\"input-label\">\u8bc4\u5206\uff1a</text>\n <input type=\"number\" v-model=\"scoreValue\" placeholder=\"\u8bf7\u8f93\u5165\u5206\u6570\" class=\"score-field\" />\n </view>\n </view>\n \n <view class=\"panel-footer\">\n <button class=\"sci-fi-button primary\" @click=\"confirmScore\">\u786e\u8ba4</button>\n <button class=\"sci-fi-button secondary\" @click=\"closeJudge\">\u5173\u95ed</button>\n </view>\n </view>\n </uni-popup>\n </view>\n</template>\n\n<script>\n// \u8fd9\u91cc\u4fdd\u7559\u539f\u6709\u7684script\u5185\u5bb9\nexport default {\n name: \"JudgeTable\",\n // ... \u5176\u4ed6\u539f\u6709\u7684script\u5185\u5bb9\n}\n</script>\n\n<style scoped>\n/* \u79d1\u5e7b\u98ce\u683c\u5bb9\u5668 */\n.sci-fi-container {\n display: flex;\n justify-content: center;\n align-items: center;\n min-height: 100vh;\n background: rgba(0, 0, 0, 0.8);\n}\n\n/* \u79d1\u5e7b\u9762\u677f\u57fa\u7840\u6837\u5f0f */\n.sci-fi-panel {\n background: linear-gradient(135deg, rgba(12, 33, 34, 0.95) 0%, rgba(0, 82, 87, 0.9) 100%);\n border: 2px solid #00f0ff;\n border-radius: 16px;\n box-shadow: \n 0 0 20px rgba(0, 240, 255, 0.3),\n inset 0 0 20px rgba(0, 240, 255, 0.1);\n position: relative;\n overflow: hidden;\n backdrop-filter: blur(10px);\n}\n\n/* \u79d1\u5e7b\u8fb9\u6846\u6548\u679c */\n.sci-fi-panel::before {\n content: '';\n position: absolute;\n top: -2px;\n left: -2px;\n right: -2px;\n bottom: -2px;\n background: linear-gradient(45deg, #00f0ff, transparent, #00f0ff, transparent, #00f0ff);\n border-radius: 16px;\n z-index: -1;\n animation: borderGlow 3s linear infinite;\n}\n\n@keyframes borderGlow {\n 0% { background-position: 0% 50%; }\n 50% { background-position: 100% 50%; }\n 100% { background-position: 0% 50%; }\n}\n\n/* \u9762\u677f\u5c3a\u5bf8 */\n.upload-panel {\n width: 600px;\n min-height: 400px;\n padding: 24px;\n}\n\n.judge-panel {\n width: 1200px;\n min-height: 600px;\n padding: 24px;\n}\n\n.judge-modal, .score-modal {\n width: 500px;\n min-height: 300px;\n padding: 24px;\n}\n\n/* \u9762\u677f\u5934\u90e8 */\n.panel-header {\n text-align: center;\n margin-bottom: 24px;\n padding-bottom: 16px;\n border-bottom: 2px solid rgba(0, 240, 255, 0.3);\n}\n\n.panel-title {\n font-size: 28px;\n font-weight: 700;\n color: #00f0ff;\n text-shadow: 0 0 10px rgba(0, 240, 255, 0.5);\n}\n\n/* \u8868\u683c\u6837\u5f0f */\n.table-header {\n display: grid;\n grid-template-columns: repeat(7, 1fr);\n gap: 1px;\n background: rgba(0, 240, 255, 0.2);\n margin-bottom: 16px;\n border-radius: 8px;\n overflow: hidden;\n}\n\n.upload-panel .table-header {\n grid-template-columns: repeat(3, 1fr);\n}\n\n.header-cell {\n background: rgba(0, 82, 87, 0.8);\n color: #00f0ff;\n padding: 12px 8px;\n text-align: center;\n font-weight: 600;\n font-size: 14px;\n}\n\n.table-content {\n max-height: 400px;\n overflow-y: auto;\n}\n\n.table-row {\n display: grid;\n grid-template-columns: repeat(7, 1fr);\n gap: 1px;\n margin-bottom: 1px;\n background: rgba(0, 240, 255, 0.1);\n border-radius: 4px;\n overflow: hidden;\n}\n\n.upload-panel .table-row {\n grid-template-columns: repeat(3, 1fr);\n}\n\n.table-cell {\n background: rgba(12, 52, 54, 0.8);\n color: #ffffff;\n padding: 12px 8px;\n text-align: center;\n font-size: 14px;\n display: flex;\n align-items: center;\n justify-content: center;\n min-height: 50px;\n}\n\n/* \u79d1\u5e7b\u6309\u94ae */\n.sci-fi-button {\n background: linear-gradient(135deg, #00ddeb 0%, #007a82 100%);\n border: 2px solid #00f0ff;\n color: #ffffff;\n padding: 12px 24px;\n border-radius: 8px;\n font-size: 16px;\n font-weight: 600;\n cursor: pointer;\n transition: all 0.3s ease;\n box-shadow: 0 0 10px rgba(0, 240, 255, 0.3);\n margin: 0 8px;\n}\n\n.sci-fi-button:hover {\n background: linear-gradient(135deg, #00f0ff 0%, #00a8b3 100%);\n box-shadow: 0 0 20px rgba(0, 240, 255, 0.6);\n transform: translateY(-2px);\n}\n\n.sci-fi-button.secondary {\n background: linear-gradient(135deg, #666666 0%, #333333 100%);\n border-color: #999999;\n}\n\n.sci-fi-button.secondary:hover {\n background: linear-gradient(135deg, #888888 0%, #555555 100%);\n box-shadow: 0 0 20px rgba(153, 153, 153, 0.6);\n}\n\n/* \u9762\u677f\u5e95\u90e8 */\n.panel-footer {\n display: flex;\n justify-content: center;\n margin-top: 24px;\n padding-top: 16px;\n border-top: 2px solid rgba(0, 240, 255, 0.3);\n}\n\n/* \u6307\u4ee4\u8f93\u5165 */\n.instruction-input input {\n width: 100%;\n background: rgba(0, 0, 0, 0.3);\n border: 1px solid #00f0ff;\n color: #ffffff;\n padding: 8px 12px;\n border-radius: 4px;\n margin-top: 8px;\n}\n\n.instruction-input input::placeholder {\n color: rgba(255, 255, 255, 0.5);\n}\n\n/* \u56fe\u7247\u6837\u5f0f */\n.instruction-image {\n width: 60px;\n height: 60px;\n border-radius: 4px;\n margin-bottom: 8px;\n}\n\n.instruction-text {\n font-size: 12px;\n word-break: break-all;\n line-height: 1.2;\n}\n\n/* \u88c1\u51b3\u6309\u94ae */\n.judge-button, .score-button {\n background: linear-gradient(135deg, #00ddeb 0%, #007a82 100%);\n border: 1px solid #00f0ff;\n color: #ffffff;\n padding: 6px 12px;\n border-radius: 4px;\n font-size: 12px;\n cursor: pointer;\n transition: all 0.3s ease;\n}\n\n.judge-button:hover, .score-button:hover {\n background: linear-gradient(135deg, #00f0ff 0%, #00a8b3 100%);\n box-shadow: 0 0 10px rgba(0, 240, 255, 0.5);\n}\n\n.judge-button:disabled {\n background: #666666;\n border-color: #999999;\n cursor: not-allowed;\n}\n\n/* \u5f39\u7a97\u5185\u5bb9\u6837\u5f0f */\n.action-info {\n margin-bottom: 20px;\n padding: 16px;\n background: rgba(0, 0, 0, 0.3);\n border-radius: 8px;\n border: 1px solid rgba(0, 240, 255, 0.3);\n}\n\n.info-row {\n display: flex;\n align-items: center;\n margin-bottom: 8px;\n}\n\n.info-row:last-child {\n margin-bottom: 0;\n}\n\n.label {\n color: #00f0ff;\n font-weight: 600;\n margin-right: 12px;\n min-width: 100px;\n}\n\n.value {\n color: #ffffff;\n flex: 1;\n}\n\n/* \u88c1\u51b3\u9009\u9879 */\n.judge-options {\n margin-bottom: 20px;\n}\n\n.group-title {\n color: #00f0ff;\n font-weight: 600;\n margin-bottom: 12px;\n display: block;\n}\n\n.radio-group {\n display: flex;\n flex-direction: column;\n gap: 8px;\n}\n\n.radio-item {\n display: flex;\n align-items: center;\n color: #ffffff;\n cursor: pointer;\n padding: 8px;\n border-radius: 4px;\n transition: background 0.3s ease;\n}\n\n.radio-item:hover {\n background: rgba(0, 240, 255, 0.1);\n}\n\n.radio-item radio {\n margin-right: 8px;\n}\n\n/* \u8bc4\u5206\u8f93\u5165 */\n.score-input {\n display: flex;\n align-items: center;\n margin-bottom: 20px;\n}\n\n.input-label {\n color: #00f0ff;\n font-weight: 600;\n margin-right: 12px;\n min-width: 60px;\n}\n\n.score-field {\n flex: 1;\n background: rgba(0, 0, 0, 0.3);\n border: 1px solid #00f0ff;\n color: #ffffff;\n padding: 8px 12px;\n border-radius: 4px;\n}\n\n.score-field::placeholder {\n color: rgba(255, 255, 255, 0.5);\n}\n\n/* \u54cd\u5e94\u5f0f\u8bbe\u8ba1 */\n@media (max-width: 768px) {\n .judge-panel {\n width: 95vw;\n padding: 16px;\n }\n \n .upload-panel {\n width: 90vw;\