default() {\n return [];\n }\n }\n },\n watch: {\n showInfo: {\n handler(newVal) {\n if (newVal.type === 'record' || newVal.type === 'judge') {\n this.getRoundTree(newVal);\n }\n },\n deep: true\n }\n },\n computed: {\n judgeOptions() {\n return [\n { value: '\u6210\u529f', label: '\u6210\u529f' },\n { value: '\u5931\u8d25', label: '\u5931\u8d25' },\n { value: '\u90e8\u5206\u6210\u529f', label: '\u90e8\u5206\u6210\u529f' }\n ];\n }\n },\n data() {\n return {\n fileList: [],\n uploadCustomStyle: {},\n recordMap: {},\n actionInfo: {},\n key: '',\n index: -1,\n eindex: -1,\n judge_result: '',\n judge_score: '',\n instructionText: '',\n toastMessage: '',\n showToast: false,\n judgeResult: '',\n scoreValue: ''\n };\n },\n filters: {\n roundPeriodFormatter(val) {\n if (val === 0) {\n return '\u51c6\u5907\u9636\u6bb5';\n }\n let stageOptions = [\n {title: '\u76f4\u7784\u5c04\u51fb\u9636\u6bb5'},\n {title: '\u673a\u52a8\u9636\u6bb5'},\n {title: '\u89e3\u9664\u538b\u5236\u9636\u6bb5'},\n {title: '\u95f4\u7784\u5c04\u51fb\u9636\u6bb5'}\n ];\n return stageOptions[val - 1].title;\n }\n },\n mounted() {\n },\n methods: {\n showCustomToast(message) {\n uni.showToast({\n title: message,\n icon: 'none',\n duration: 1500\n });\n }\n }\n};\n</script>"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"现在让我重新创建一个干净的文件：
