 87				console.log('res: ', res);
 88				this.verdictRecordList = res.data.data.rows;
 89				this.total = res.data.data.total;
 90				this.verdictRecordList.forEach(async (item) => {
 91					if (item.cover) {
 92						let oss = await getOssById(item.cover);
 93						let coverUrl = this.baseOssIpPort + oss.data.data.fileName;
 94						this.$set(item, 'coverUrl', coverUrl);
 95					}
 96				});
 97				// this.VerdictRecordList = rst.result.records;
 98			},
