 68	<script>
 69	import { getOssById } from '@/api/system.js';
 70	import { queryUnfinishedList } from '@/api/verdictRecord';
 71	import { joinRoom, queryCampList, chooseCamp } from '@/api/room.js';
 72	import { initWebSocket, sendMsg } from '@/api/websocket.js';
 73	import NavBar from "@/uni_modules/nav-bar/nav-bar.vue";
 74	import NjustPopup from "@/uni_modules/njust-popup/njust-popup.vue";
 75	export default {
 76	 components: {NjustPopup, NavBar},
 77	 data() {
 78	 return {
 79	 verdictRecordList: [],
 80	 campList:[],
 81	 user: {},
 82	 currRecordId:'',
 83	 inviteCode: '',
 84	 campId: '',
 85	 userType: 1, // 固定为操作员
 86	 isAdmin: false,
 87	 isUser: true,
 88	 queryParams: {
 89	 pageSize: 10,
 90	 pageNum: 1,
 91	 productId: ''
 92	 },
 93	 total: 0,
 94	
 95	 isModalVisible: false,
 96	 currentItem : '',
 97	 };
 98	 },
 99	 onLoad(option) {
 100	 initWebSocket();
 101	 this.user = uni.getStorageSync('user');
 102	 console.log(option)
 103	 if (option.productId) {
 104	 this.queryParams.productId = option.productId;
 105	 }
 106	 if(option.isAdmin){
 107	 this.isAdmin = JSON.parse(option.isAdmin);
 108	 }
 109	 if(option.isUser){
 110	 this.isUser = JSON.parse(option.isUser);
 111	 }
 112	 this.queryVerdictRecordListFunc();
 113	 },
 114	 methods: {
 115	 async queryVerdictRecordListFunc() {
 116	 this.verdictRecordList = [];
 117	 console.log('this.queryParams: ', this.queryParams);
 118	 let res = await queryUnfinishedList(this.queryParams);
 119	 console.log('res: ', res);
 120	 console.log('res.data.data.rows: ', res.data.data.rows);
 121	 this.verdictRecordList = res.data.data.rows;
 122	 this.total = res.data.data.total;
 123	 this.verdictRecordList.forEach(async (item) => {
 124	 if (item.cover) {
 125	 let oss = await getOssById(item.cover);
 126	 let coverUrl = this.baseOssIpPort + oss.data.data.fileName;
 127	 this.$set(item, 'coverUrl', coverUrl);
 128	 }
 129	 });
 130	 },
 131	 nativeTo(item) {
 132	 if(!this.isAdmin) return;
 133	 let status = item.status;
 134	 if(status === 10){
 135	 uni.navigateTo({
 136	 url:
 137	 '/pages/room/create?inviteCode=' +
 138	 item.inviteCode +
 139	 '&verdictRecordId=' +
 140	 item.verdictRecordId +
 141	 '&isAdmin=' + this.isAdmin
 142	 });
 143	 }else{
 144	 uni.navigateTo({
 145	 url:
 146	 '/pages/wargame/index-v2?verdictRecordId=' +
 147	 item.verdictRecordId +
 148	 '&isUser=' +
 149	 this.isUser +
 150	 '&campId=' +
 151	 item.campId
 152	 });
 153	 }
 154	 },
 155	 toEdit()
 156	 {
 157	 uni.navigateTo({
 158	 url: '/pages/chess-pieces/scenarioEdit?productId=' + this.queryParams.productId
 159	 });
 160	 },
 161	
 162	 pageChange(e) {
 163	 console.log('e: ', e);
 164	 this.queryParams.pageNum = e.current;
 165	 this.queryVerdictRecordListFunc();
 166	 },
 167	 createOne(){
 168	 console.log('create')
 169	 uni.navigateTo({
 170	 url: '/pages/chess-pieces/select?id=' + this.queryParams.productId
 171	 });
 172	 },
 173	 showModal(item){
 174	 if (this.isAdmin) return
 175	 this.$refs.isModalVisible.open();
 176	 this.isModalVisible = true;
 177	 this.currentItem = item;
 178	 console.log(item)
 179	 },
 180	 toRoom(type,item){
 181	
 182	 this.$refs.isModalVisible.close();
 183	
 184	 this.currRecordId = item.verdictRecordId;
 185	 this.inviteCode = item.inviteCode;
 186	 let itemCampId = '';
 187	 if(this.user.id === item.firstUserId){
 188	 itemCampId = item.firstCampId;
 189	 }else if(this.user.id === item.secondUserId){
 190	 itemCampId = item.secondCampId;
 191	 }
 192	 switch (type) {
 193	 case '0' :
 194	 queryCampList({ verdictRecordId: item.verdictRecordId })
 195	 .then((res) => {
 196	 console.log(res)
 197	 this.campList = res.data.data;
 198	 this.campList.forEach((item) => {
 199	 item.text = item.name;
 200	 item.value = item.id;
 201	 });
 202	 this.$refs.camp.open();
 203	 })
 204	 .catch((err) => {});
 205	 break;
 206	 case '1' :
 207	 uni.navigateTo({
 208	 url:
 209	 '/pages/wargame/index-v2?verdictRecordId=' +
 210	 this.currRecordId +
 211	 '&isUser=' +
 212	 !this.isAdmin +
 213	 '&campId=' +
 214	 itemCampId
 215	 });
 216	 break;
 217	 case '2' :
 218	 sendMsg(JSON.stringify({ action: 'watchJoinRoom', verdictRecordId: this.currRecordId }));
 219	 uni.navigateTo({
 220	 url: '/pages/wargame/index-v2?verdictRecordId=' + this.currRecordId + '&type=watch'
 221	 });
 222	 break;
 223	 case '3' :
 224	 uni.navigateTo({
 225	 url:
 226	 '/pages/room/create?inviteCode=' +
 227	 this.inviteCode +
 228	 '&verdictRecordId=' +
 229	 this.currRecordId +
 230	 '&campId=' +
 231	 itemCampId
 232	 });
 233	 }
 234	 },
 235	 chooseCamp() {
 236	 if(this.campId === ''){
 237	 uni.showToast({
 238	 title: '请选择阵营',
 239	 icon: 'none'
 240	 })
 241	 return;
 242	 }
 243	 chooseCamp({ id: this.campId, verdictRecordId: this.currRecordId, userType: this.userType })
 244	 .then((res) => {
 245	 console.log(res)
 246	 if (res.data.code === 200) {
