 418	 style="width: 11% ; background-color: transparent ;color: white">
 419	 {{ item.roundPeriod | roundPeriodFormatter }}
 420	 </td>
 421	 <td v-if="eindex === 0" :rowspan="item.historyVoList.length" align="center"
 422	 style="width: 10% ; background-color: transparent ;color: white">
