 431	 <td v-else-if="showInfo.type === 'judge'" style="text-align:left; padding: 0;" >
 432	 <button @click="judgeOneByOne(eitem, key, index, eindex)" :disabled="eitem.status === 2" style="width: 120px;white-space: nowrap;margin: 0;">
 433	 {{ eitem.status !== 2 ? '裁决' : '已裁决' }}
 434	 </button>
 435	 </td>
 436	 <td v-if="showInfo.type === 'record'" align="center" class="col6" style="color: white">
 437	 {{ eitem.attackScore }}
 438	 </td>
 439	 <td v-if="showInfo.userType === 'admin' && eitem.attackScore" align="center" class="col6"
