 444		methods: {
 445			// websocket 接收信息
 446			onMessage() {
 447				uni.$on('onMessage', (res) => {
 448					let jsonRes = JSON.parse(res.data);
 449					let action = jsonRes.action;
 450					switch (action) {
 451						case 'shakeDice':
 452							this.$refs.popupRule.close();
 453							let diceArr = jsonRes.data;
 454							this.shakeDice(diceArr);
 455							break;
 456						case 'lookUpTable':
 457							this.getRuleList();
 458							break;
 459						case 'colseTable':
 460							break;
 461						case 'takeAction':
 462							this.queryAllFunc();
 463							break;
 464						case 'endRound':
 465							//更新管理员看到的提交状态
 466							this.getRoundStatus();
 467							break;
 468						case 'judge':
 469							//裁决结果展示
 470							let judgeData = jsonRes.data;
 471							this.judgeShow(judgeData);
 472							break;
 473						case 'refresh':
 474							this.refresh();
 475							break;
 476						default:
 477							break;
 478					}
 479				});
 480			},
