 505			async judge() {
 506				let data = {
 507					verdictRecordId: this.verdictRecordId,
 508					chessRound: this.roundActive,
 509					roundPeriod: this.stageActive + 1
 510				};
 511				let res = await judge(data);
 512				let resultData = res.data.data;
 513				console.log('resultData: ', resultData.length);
 514				if (resultData.length > 0) {
 515					sendMsg(
 516						JSON.stringify({
 517							action: 'judge',
 518							verdictRecordId: this.verdictRecordId,
 519							data: resultData
 520						})
 521					);
 522				} else {
 523					sendMsg(
 524						JSON.stringify({
 525							action: 'takeAction',
 526							verdictRecordId: this.verdictRecordId
 527						})
 528					);
 529				}
 530			},
