 716			async submitScore(scoreList) {
 717				for (let i in scoreList) {
 718					scoreList[i].campId = this.campListItem.campId;
 719					scoreList[i].campName = this.campListItem.campName;
 720					scoreList[i].userId = this.campListItem.userId;
 721					scoreList[i].userName = this.campListItem.userName;
 722					scoreList[i].verdictRecordId = this.campListItem.verdictRecordId;
 723					scoreList[i].chessRound = this.campListItem.chessRound;
 724				}
 725				let res = await submitScore(scoreList);
 726				if (res.data.code == 200) {
 727					uni.showToast({
 728						title: '提交成功',
 729						icon: 'none',
 730						duration: 1500
 731					});
 732					this.$refs.scoreTable.close();
 733					this.scoreList = [];
 734				} else {
 735					uni.showToast({
 736						title: '提交失败！',
 737						icon: 'error',
 738						duration: 1500
 739					});
 740				}
 741				console.log(res);
 742			},
