 601			formatterStatusDesc(newVal) {
 602				if (this.isAdmin) {
 603					let n = 0;
 604					for (let i in newVal) {
 605						if (newVal[i].status == 1) {
 606							n++;
 607						}
 608					}
 609					if (n == 0) {
 610						this.statusDesc = '未提交';
 611						this.roundEnd = false;
 612					} else if (n == 1) {
 613						this.statusDesc = '一方已提交';
 614						this.roundEnd = false;
 615					} else {
 616						this.statusDesc = '已提交';
 617						this.roundEnd = true;
 618					}
 619				} else {
 620					let n = 0;
 621					for (let i in newVal) {
 622						if (newVal[i].campId == this.campId && newVal[i].status == 1) {
 623							n++;
 624						}
 625					}
 626					if (n == 0) {
 627						this.statusDesc = '未提交';
 628						this.userStageNotSubmit = true;
 629					} else if (n == 1) {
 630						this.statusDesc = '已提交';
 631						this.userStageNotSubmit = false;
 632					}
 633				}
 634				this.statusIndex = 1;
 635				console.log('this.statusDesc: ', this.statusDesc);
 636			},
 637			async getRealTimeScore() {
 638				let queryScoreData = {
 639					verdictRecordId: this.verdictRecordId
 640				};
 641				let scoreListResult = await getRealTimeScore(queryScoreData);
 642				let realTimeScoreList = scoreListResult.data.data;
 643				console.log('realTimeScoreList: ', realTimeScoreList);
 644				this.realTimeScore.firstScoretypeTotal = 0;
 645				this.realTimeScore.secondScoretypeTotal = 0;
 646				this.realTimeScore.firstCampName = this.campList[0].campName;
 647				this.realTimeScore.secondCampName = this.campList[1].campName;
 648				for (var i in realTimeScoreList) {
 649					if (this.campList[0].campId == realTimeScoreList[i].campId) {
 650						if (realTimeScoreList[i].type == 1) {
 651							this.realTimeScore.firstScoretype1 = realTimeScoreList[i].score;
 652						} else if (realTimeScoreList[i].type == 2) {
 653							this.realTimeScore.firstScoretype2 = realTimeScoreList[i].score;
 654						} else if (realTimeScoreList[i].type == 3) {
 655							this.realTimeScore.firstScoretype3 = realTimeScoreList[i].score;
 656						}
 657						this.realTimeScore.firstScoretypeTotal += realTimeScoreList[i].score;
 658					} else {
 659						if (realTimeScoreList[i].type == 1) {
 660							this.realTimeScore.secondScoretype1 = realTimeScoreList[i].score;
 661						} else if (realTimeScoreList[i].type == 2) {
 662							this.realTimeScore.secondScoretype2 = realTimeScoreList[i].score;
 663						} else if (realTimeScoreList[i].type == 3) {
 664							this.realTimeScore.secondScoretype3 = realTimeScoreList[i].score;
 665						}
 666						this.realTimeScore.secondScoretypeTotal += realTimeScoreList[i].score;
 667					}
 668				}
 669				this.$refs.showRealTimeScore.open();
 670			},
