 876			gen() {
 877				this.mapLong = this.map.longitudinalDimension;
 878				this.mapWidth = this.map.transverseDimension;
 879	
 880				this.mapList = [];
 881				for (let i = 0; i < this.mapLong; i++) {
 882					this.mapList.push([]);
 883					for (let j = 0; j < this.mapWidth; j++) {
 884						let data = {
 885							coordinate:
 886								(this.mapLong - i).toString().padStart(2, '0') + (j + 1).toString().padStart(2, '0'),
 887							chessPiecesNumber: '',
 888							chessPiecesName: '',
 889							chessPiecesCover: ''
 890						};
 891						this.mapList[i].push(data);
 892					}
 893				}
 894				setTimeout(() => {
 895					this.arrange();
 896				}, 5);
 897			},
 898			arrange() {
 899				let offsetTop = 0;
 900				let lineIndex = 0;
 901				document.querySelectorAll('.block').forEach((item) => {
 902					item.style.marginLeft = '0px';
 903					if (offsetTop !== item.offsetTop) {
 904						++lineIndex;
 905						if (lineIndex % 2 === 0) {
 906							item.style.marginLeft = 66.8 * 0.5 + 'px';
 907							// parseInt(this.width) * 0.5 + parseInt(this.marginLeftRight) * 0.5 + 0 + 'px';
 908						}
 909					}
 910					offsetTop = item.offsetTop;
 911				});
 912			},
 913			async queryAllFunc() {
 914				let data = {
 915					id: this.verdictRecordId
 916				};
 917				let rst = await queryVerdictResult(data);
 918				let resultData = rst.data.data;
 919				for (var key in resultData) {
 920					this.game[key] = resultData[key];
 921				}
 922				this.roundActive = this.game.chessRound;
 923				if (this.user.id == this.game.inviterUserId) {
 924					this.isAdmin = true;
 925				}
 926				//格式化campList
 927				this.formatterCampList();
 928				this.chessRoundLimit = resultData.chessRoundLimit;
 929				this.initialRoundOptions(this.chessRoundLimit);
 930				this.queryChessRoundFunc();
 931				this.getRoundStatus();
 932				if (this.game.status < 30) {
 933					this.game.nowRound = 0;
 934				} else {
 935					this.game.nowRound = this.game.chessRound;
 936				}
 937				if (this.game.status == 50) {
 938					let result = this.game.verdictResult;
 939					this.game.resultStr = '';
 940					if (result == 20) {
 941						this.game.result = 0;
 942						this.game.resultStr = '双方平局';
 943					} else if (result == 10) {
 944						if (this.game.firstCampId == this.campId) {
 945							this.game.result = 1;
 946						} else {
 947							this.game.result = 2;
 948						}
 949						this.game.resultStr = this.game.firstCampName + '击败了' + this.game.secondCampName;
 950					} else {
 951						if (this.game.firstCampId == this.campId) {
 952							this.game.result = 2;
 953						} else {
 954							this.game.result = 1;
 955						}
 956						this.game.resultStr = this.game.secondCampName + '击败了' + this.game.firstCampName;
 957					}
 958					if (this.isAdmin) {
 959						this.getTableScoreFinal();
 960						// this.$refs.scoreTableFinal.open();
 961					} else {
 962						this.$refs.showResult.open();
 963					}
 964					// this.$refs.showResult.open();
 965					// this.$refs.showSettlement.open();
 966				}
 967	
 968				if (this.game.baseRound != this.game.chessRound) {
 969					this.isAttack = false;
 970					this.isMove = false;
 971					let data = {
 972						chessRound: this.game.chessRound,
 973						userId: this.user.id,
 974						verdictRecordId: this.verdictRecordId
 975					};
 976					queryActionEffect(data).then((res) => {
 977						this.game.settlement = res.data.data;
 978						//this.game.showSettlement = true
 979						this.game.baseRound = this.game.chessRound;
 980					});
 981				}
 982				// if (this.game.status >= 30) {
 983				// 	this.isOwnRoundFunc();
 984				// }
 985	
 986				// if (!this.isUser | !this.game.isOwn) {
 987				this.queryUsChessPiecesInfoFunc();
 988				// }
 989			},
 990			queryChessRoundFunc() {
 991				if (this.game.roundPeriod == 1) {
 992					this.game.roundDesc = '直瞄射击阶段';
 993					this.stageActive = 0;
 994				}
 995				if (this.game.roundPeriod == 2) {
 996					this.game.roundDesc = '机动阶段';
 997					this.stageActive = 1;
 998				}
 999				if (this.game.roundPeriod == 3) {
 1000					this.game.roundDesc = '压制标记的移除阶段';
 1001					this.stageActive = 2;
 1002				}
 1003				if (this.game.roundPeriod == 4) {
 1004					this.game.roundDesc = '间射击阶段';
 1005					this.stageActive = 3;
 1006				}
 1007				this.queryPromptFunc();
 1008			},
 1009			formatterCampList() {
 1010				this.campList = [];
 1011				let dataFirst = {
 1012					campId: this.game.firstCampId,
 1013					campName: this.game.firstCampName,
 1014					userId: this.game.firstUserId,
 1015					userName: this.game.firstUserName,
 1016					verdictRecordId: this.verdictRecordId
 1017				};
 1018				this.campList.push(dataFirst);
 1019				let dataSecond = {
 1020					campId: this.game.secondCampId,
 1021					campName: this.game.secondCampName,
 1022					userId: this.game.secondUserId,
 1023					userName: this.game.secondUserName,
 1024					verdictRecordId: this.verdictRecordId
 1025				};
 1026				this.campList.push(dataSecond);
 1027				if (this.isAdmin) {
 1028					this.avatarText = '导演';
 1029				} else if (this.user.id == this.game.firstUserId) {
 1030					this.avatarText = this.game.firstCampName;
 1031				} else if (this.user.id == this.game.secondUserId) {
 1032					this.avatarText = this.game.secondCampName;
 1033				}
 1034				console.log('this.user.id: ', this.user.id);
 1035				console.log('this.game.firstUserId: ', this.game.firstUserId);
 1036				console.log('this.game.secondUserId: ', this.game.secondUserId);
 1037			},
 1038			async isOwnRoundFunc() {
 1039				let data = {
 1040					id: this.verdictRecordId,
