 1044				this.game.isOwn = res.data.data;
 1045			},
 1046			async queryUsChessPiecesInfoFunc() {
 1047				let data = {
 1048					verdictRecordId: this.verdictRecordId,
 1049					chessRound: this.game.chessRound,
 1050					roundPeriod: this.stageActive + 1
 1051				};
 1052				let res = '';
 1053				if (this.isUser) {
 1054					data.campId = this.campId;
 1055					res = await queryAllChessPiecesInfo(data);
 1056				} else {
 1057					res = await queryAllChessPiecesInfo(data);
 1058				}
 1059				for (let itemk of this.mapList)
 1060					for (let h of itemk) {
 1061						h.chessPiecesNumber = '';
 1062						h.chessPiecesName = '';
 1063						h.chessPiecesCover = '';
 1064						h.chessPiecesCampId = '';
 1065						h.statusDesc = '';
 1066						h.status = 10;
 1067					}
 1068				this.game.userPiece = [];
 1069				for (let item of res.data.data) {
 1070					item.isAdd = false;
 1071					item.canMove = true;
 1072					item.isDie = false;
 1073					this.game.userPiece.push(item);
 1074					for (let itemk of this.mapList)
 1075						for (let h of itemk) {
 1076							if (h.coordinate == item.coordinate) {
