 177	import {saveRoundCover, getHistoryTreeByRound, confirmJudge, saveTextInstruction} from '@/api/verdictRecord.js';
 178	
 179	export default {
 180	 name: 'judge-table',
 181	 props: {
 182	 showInfo: {
 183	 type: Object,
 184	 default() {
 185	 return {
 186	 userType: '',
 187	 type: '',
 188	 chessRound: 0,
 189	 roundPeriod: 0,
 190	 roundPeriodName: '',
 191	 verdictRecordId: undefined,
 192	 campId: undefined,
 193	 textIns: '',
 194	 };
 195	 }
 196	 },
 197	 stageOptions: {
 198	 type: Array,
 199	 default() {
 200	 return [];
 201	 }
 202	 }
 203	 },
 204	 watch: {
 205	 showInfo: {
 206	 handler(newVal) {
 207	 if (newVal.type === 'record' || newVal.type === 'judge') {
 208	 this.getRoundTree(newVal);
 209	 }
 210	 },
 211	 deep: true
 212	 }
 213	 },
 214	 computed: {
 215	 judgeOptions() {
 216	 return [
 217	 { value: '成功', label: '成功' },
 218	 { value: '失败', label: '失败' },
 219	 { value: '部分成功', label: '部分成功' }
 220	 ];
 221	 }
 222	 },
 223	 data() {
 224	 return {
 225	 fileList: [],
 226	 uploadCustomStyle: {},
 227	 recordMap: {},
 228	 actionInfo: {},
 229	 key: '',
 230	 index: -1,
 231	 eindex: -1,
 232	 judge_result: '',
 233	 judge_score: '',
 234	 instructionText: '',
 235	 toastMessage: '',
 236	 showToast: false,
 237	 judgeResult: '',
 238	 scoreValue: ''
 239	 };
 240	 },
 241	 filters: {
 242	 roundPeriodFormatter(val) {
 243	 if (val === 0) {
 244	 return '准备阶段';
 245	 }
 246	 let stageOptions = [
 247	 {title: '直瞄射击阶段'},
 248	 {title: '机动阶段'},
 249	 {title: '解除压制阶段'},
 250	 {title: '间瞄射击阶段'}
 251	 ];
 252	 return stageOptions[val - 1].title;
 253	 }
 254	 },
 255	 mounted() {
 256	 },
 257	 methods: {
 258	 showCustomToast(message) {
 259	 uni.showToast({
 260	 title: message,
 261	 icon: 'none',
 262	 duration: 1500
 263	 });
 264	 },
 265	
 266	 confirmJudge(notJudgeNumber) {
 267	 this.recordMap[this.key][this.index].historyVoList[this.eindex].status = 2;
 268	 if (this.showInfo.userType === 'admin') {
 269	 this.recordMap[this.key][this.index].historyVoList[this.eindex].attackScore = this.scoreValue;
 270	 } else {
 271	 this.recordMap[this.key][this.index].historyVoList[this.eindex].attackResult = this.judgeResult;
 272	 }
 273	 console.log('裁决完毕')
 274	 this.$emit('judgeComplete');
 275	 },
 276	
 277	 confirmJudgeAction() {
 278	 if (!this.judgeResult) {
 279	 this.showCustomToast('请选择裁决结果');
 280	 return;
 281	 }
 282	 this.judge_result = this.judgeResult;
 283	 this.submitJudge();
 284	 },
 285	
 286	 confirmScore() {
 287	 if (!this.scoreValue) {
 288	 this.showCustomToast('请输入评分');
 289	 return;
 290	 }
 291	 this.judge_score = this.scoreValue;
 292	 this.submitJudge();
 293	 },
 294	
 295	 submitJudge() {
 296	 if (this.showInfo.userType === 'admin') {
 297	 this.actionInfo.attackScore = this.judge_score;
 298	 } else {
 299	 this.actionInfo.attackResult = this.judge_result;
 300	 }
 301	
 302	 confirmJudge(this.actionInfo).then((res) => {
 303	 if (res.data.code === 200) {
 304	 this.showCustomToast("提交成功");
 305	 this.confirmJudge(res.data.data);
 306	
 307	 this.judge_result = '';
 308	 this.judge_score = '';
 309	 this.judgeResult = '';
 310	 this.scoreValue = '';
 311	
 312	 setTimeout(() => {
 313	 this.closeJudge();
 314	 }, 1000);
 315	 } else {
 316	 this.showCustomToast(res.data.msg || '提交失败');
 317	 }
 318	 }).catch(err => {
 319	 this.showCustomToast('网络错误，请重试');
 320	 });
 321	 },
 322	
 323	 stepJudge() {
 324	 this.$refs.popup.close();
 325	 this.$emit('stepJudge');
 326	 },
 327	
 328	 judgeOneByOne(eitem, key, index, eindex) {
 329	 this.key = key;
 330	 this.index = index;
 331	 this.eindex = eindex;
 332	 this.actionInfo = eitem;
 333	 if (this.showInfo.userType === 'admin') {
 334	 this.$refs.scorePopup.open();
 335	 } else {
 336	 this.$refs.judgePopup.open();
 337	 }
 338	 },
 339	
 340	 open() {
 341	 this.$refs.popup.open();
 342	 },
 343	
 344	 close() {
 345	 this.$refs.popup.close();
 346	 },
 347	
 348	 closeJudge() {
 349	 this.$refs.judgePopup.close();
 350	 this.$refs.scorePopup.close();
 351	 this.judge_result = '';
 352	 this.judge_score = '';
 353	 this.judgeResult = '';
 354	 this.scoreValue = '';
 355	 },
 356	
 357	 imageClick(url) {
 358	 uni.previewImage({
 359	 urls: [url]
 360	 });
 361	 },
 362	
 363	 async getRoundTree(item) {
 364	 let res = await getHistoryTreeByRound(item);
 365	 let resArray = res.data.data;
 366	 resArray = resArray.filter((item) => {
 367	 item.historyVoList = item.historyVoList.filter((item) => item.actionDesc);
 368	 return item.historyVoList.length > 0;
 369	 });
 370	 if (resArray.length === 0) {
 371	 this.recordMap = {};
 372	 } else {
 373	 this.recordMap = this.groupBy(resArray, 'chessRound');
 374	 }
 375	 },
 376	
 377	 groupBy(arr, key) {
 378	 let obj = {};
 379	 arr.forEach((item) => {
 380	 if (!obj[item[key]]) {
 381	 obj[item[key]] = [];
 382	 }
 383	 obj[item[key]].push(item);
 384	 });
 385	 return obj;
 386	 },
 387	
 388	 deletePic(e) {
 389	 this.fileList.splice(e.index, 1);
 390	 },
 391	
 392	 async afterRead(event) {
 393	 let lists = [].concat(event.file);
 394	 let fileListLen = this.fileList.length;
 395	 lists.map((item) => {
 396	 this.fileList.push({
 397	 ...item,
 398	 status: 'uploading',
 399	 message: '上传中'
 400	 });
 401	 });
 402	
 403	 for (let i = 0; i < lists.length; i++) {
 404	 const result = await this.uploadFilePromise(lists[i].url);
 405	 let item = this.fileList[fileListLen];
 406	 this.fileList.splice(
 407	 fileListLen,
 408	 1,
 409	 Object.assign(item, {
 410	 status: 'success',
 411	 message: '',
 412	 url: result
 413	 })
 414	 );
 415	 fileListLen++;
 416	 }
 417	 },
 418	
 419	 uploadFilePromise(avatarUrl) {
 420	 return new Promise((resolve, reject) => {
 421	 uni.uploadFile({
 422	 url: baseURL + 'system/upload',
 423	 filePath: avatarUrl,
 424	 name: 'file',
 425	 header: {
 426	 Authorization: getUserTokenStorage()
 427	 },
 428	 success: (uploadFileRes) => {
 429	 let jsonRes = JSON.parse(uploadFileRes.data);
 430	 setTimeout(() => {
 431	 resolve(jsonRes.data.url);
 432	 }, 1000);
 433	 },
 434	 fail: (error) => {
 435	 reject(error);
 436	 }
 437	 });
 438	 });
 439	 },
 440	
 441	 async submitInstruct() {
 442	 if ((!this.instructionText || !this.instructionText.trim()) && this.fileList.length === 0) {
 443	 return this.showCustomToast('请至少上传图片或输入文本');
 444	 }
 445	
 446	 let textSaved = false;
 447	 let imageSaved = false;
 448	 let hasError = false;
 449	
 450	 if (this.instructionText && this.instructionText.trim()) {
 451	 this.showInfo.textIns = this.instructionText;
 452	 try {
 453	 let resText = await saveTextInstruction(this.showInfo);
 454	 if (resText.data && resText.data.code === 200) {
 455	 textSaved = true;
 456	 } else {
 457	 hasError = true;
 458	 }
 459	 } catch (error) {
 460	 hasError = true;
 461	 }
 462	 }
 463	
 464	 if (this.fileList.length !== 0) {
 465	 this.showInfo.coverUrl = this.fileList[0].url;
 466	 try {
 467	 let resCover = await saveRoundCover(this.showInfo);
 468	 if (resCover.data && resCover.data.code === 200) {
 469	 imageSaved = true;
 470	 } else {
 471	 hasError = true;
 472	 }
 473	 } catch (error) {
 474	 hasError = true;
 475	 }
 476	 }
 477	
 478	 if (hasError) {
 479	 this.showCustomToast('保存失败');
 480	 } else if (textSaved || imageSaved) {
 481	 this.showCustomToast('保存成功');
 482	 this.fileList = [];
 483	 this.instructionText = '';
 484	 this.$refs.popup.close();
 485	 }
 486	 }
 487	 }
 488	};
 489	</script>
