 72	 <view class="header-cell">◆ 指挥员指令 ◆</view>
 73	 <view class="header-cell">◆ 单位 ◆</view>
 74	 <view class="header-cell">◆ 部队动作 ◆</view>
 75	 <view class="header-cell">◆ 裁决结果 ◆</view>
 76	 <view class="header-cell">◆ 裁决得分 ◆</view>
 77	 </view>
 78	 
 79	 <view class="table-content">
 80	 <view v-for="(value, key) in recordMap" :key="key + 'map'" class="round-group">
 81	 <view v-for="(item, index) in value" :key="index" class="instruction-group">
 82	 <view v-for="(eitem, eindex) in item.historyVoList" :key="eindex" class="table-row">
 83	 <view v-if="eindex === 0" class="table-cell round-cell" :style="{height: (item.historyVoList.length * 50) + 'px'}">
 84	 第{{ key }}回合
 85	 </view>
 86	 <view v-if="eindex === 0" class="table-cell stage-cell" :style="{height: (item.historyVoList.length * 50) + 'px'}">
 87	 {{ item.roundPeriod | roundPeriodFormatter }}
 88	 </view>
 89	 <view v-if="eindex === 0" class="table-cell instruction-cell" :style="{height: (item.historyVoList.length * 50) + 'px'}">
 90	 <uv-image @click="imageClick(item.coverUrl)" :src="item.coverUrl" class="instruction-image"></uv-image>
 91	 <view class="instruction-text">{{ item.textIns }}</view>
 92	 </view>
 93	 <view class="table-cell unit-cell">{{ eitem.chessPiecesNumber }}</view>
 94	 <view class="table-cell action-cell">{{ eitem.actionDesc }}</view>
 95	 <view v-if="showInfo.type === 'record' || showInfo.userType === 'admin'" class="table-cell result-cell">
 96	 {{ eitem.attackResult }}
 97	 </view>
 98	 <view v-else-if="showInfo.type === 'judge'" class="table-cell judge-cell">
 99	 <button @click="judgeOneByOne(eitem, key, index, eindex)" :disabled="eitem.status === 2" class="judge-button">
 100	 {{ eitem.status !== 2 ? '裁决' : '已裁决' }}
 101	 </button>
 102	 </view>
 103	 <view v-if="showInfo.type === 'record'" class="table-cell score-cell">
 104	 {{ eitem.attackScore }}
 105	 </view>
 106	 <view v-if="showInfo.userType === 'admin' && eitem.attackScore" class="table-cell score-cell">
 107	 <button @click="judgeOneByOne(eitem, key, index, eindex)" class="score-button">{{ eitem.attackScore }}</button>
 108	 </view>
 109	 <view v-else-if="showInfo.userType === 'admin' && !eitem.attackScore" class="table-cell score-cell">
 110	 <button @click="judgeOneByOne(eitem, key, index, eindex)" class="score-button">打分</button>
 111	 </view>
 112	 </view>
 113	 </view>
 114	 </view>
 115	 </view>
 116	 </view>
 117	 
 118	 <view class="panel-footer">
 119	 <button v-if="Object.keys(recordMap).length === 0 && showInfo.userType === 'judge'" class="sci-fi-button secondary" @click="stepJudge">
 120	 <text class="button-icon">⏭</text> 跳过
 121	 </button>
 122	 <button class="sci-fi-button primary" @click="close">
 123	 <text class="button-icon">✕</text> 关闭
 124	 </button>
 125	 </view>
 126	 </view>
 127	 </view>
 128	 </uni-popup>
 129	
 130	 <!-- 裁决弹窗 -->
 131	 <uni-popup ref="judgePopup" :mask-click="false">
 132	 <view class="sci-fi-panel judge-modal">
 133	 <view class="panel-header">
 134	 <view class="panel-title">◆ 部队行动裁决 ◆</view>
 135	 <view class="military-code">UNIT ACTION JUDGMENT</view>
 136	 </view>
 137	 
 138	 <view class="panel-content">
 139	 <view class="action-info">
 140	 <view class="info-row">
 141	 <text class="label">部队行动：</text>
 142	 <text class="value">{{ actionInfo.actionDesc }}</text>
 143	 </view>
 144	 </view>
 145	 
 146	 <view class="judge-options">
 147	 <view class="option-group">
 148	 <text class="group-title">请选择裁决结果：</text>
 149	 <view class="radio-group">
 150	 <label v-for="item in judgeOptions" :key="item.value" class="radio-item" @click="judgeResult = item.value">
 151	 <radio :checked="judgeResult === item.value" :value="item.value" />
 152	 <text>{{ item.label }}</text>
 153	 </label>
 154	 </view>
 155	 </view>
 156	 </view>
 157	 </view>
 158	 
 159	 <view class="panel-footer">
 160	 <button class="sci-fi-button primary" @click="confirmJudgeAction">
 161	 <text class="button-icon">✓</text> 确认
 162	 </button>
 163	 <button class="sci-fi-button secondary" @click="closeJudge">
 164	 <text class="button-icon">✕</text> 关闭
 165	 </button>
 166	 </view>
 167	 </view>
 168	 </uni-popup>
 169	
 170	 <!-- 评分弹窗 -->
 171	 <uni-popup ref="scorePopup" :mask-click="false">
 172	 <view class="sci-fi-panel score-modal">
 173	 <view class="panel-header">
 174	 <view class="panel-title">◆ 评分输入系统 ◆</view>
 175	 <view class="military-code">SCORING INPUT SYSTEM</view>
 176	 </view>
 177	 
 178	 <view class="panel-content">
 179	 <view class="action-info">
 180	 <view class="info-row">
 181	 <text class="label">部队行动：</text>
 182	 <text class="value">{{ actionInfo.actionDesc }}</text>
 183	 </view>
 184	 </view>
 185	 
 186	 <view class="score-input">
 187	 <text class="input-label">评分：</text>
 188	 <input type="number" v-model="scoreValue" placeholder="请输入分数" class="score-field" />
 189	 </view>
 190	 </view>
 191	 
 192	 <view class="panel-footer">
 193	 <button class="sci-fi-button primary" @click="confirmScore">
 194	 <text class="button-icon">✓</text> 确认
 195	 </button>
 196	 <button class="sci-fi-button secondary" @click="closeJudge">
 197	 <text class="button-icon">✕</text> 关闭
 198	 </button>
 199	 </view>
 200	 </view>
 201	 </uni-popup>
 202	 </view>
 203	</template>
 204	
 205	<script>
 206	import {baseURL, getUserTokenStorage} from '@/api/http.js';
 207	import {saveRoundCover, getHistoryTreeByRound, confirmJudge, saveTextInstruction} from '@/api/verdictRecord.js';
 208	
 209	export default {
 210	 name: 'judge-table',
 211	 props: {
 212	 showInfo: {
 213	 type: Object,
 214	 default() {
 215	 return {
 216	 userType: '',
 217	 type: '',
 218	 chessRound: 0,
 219	 roundPeriod: 0,
 220	 roundPeriodName: '',
 221	 verdictRecordId: undefined,
 222	 campId: undefined,
 223	 textIns: '',
 224	 };
 225	 }
 226	 },
 227	 stageOptions: {
 228	 type: Array,
 229	 default() {
 230	 return [];
 231	 }
 232	 }
 233	 },
 234	 watch: {
 235	 showInfo: {
 236	 handler(newVal) {
 237	 if (newVal.type === 'record' || newVal.type === 'judge') {
 238	 this.getRoundTree(newVal);
 239	 }
 240	 },
 241	 deep: true
 242	 }
 243	 },
 244	 computed: {
 245	 judgeOptions() {
 246	 return [
 247	 { value: '成功', label: '成功' },
 248	 { value: '失败', label: '失败' },
 249	 { value: '部分成功', label: '部分成功' }
 250	 ];
 251	 }
 252	 },
 253	 data() {
 254	 return {
 255	 fileList: [],
 256	 uploadCustomStyle: {},
 257	 recordMap: {},
 258	 actionInfo: {},
 259	 key: '',
 260	 index: -1,
 261	 eindex: -1,
 262	 judge_result: '',
 263	 judge_score: '',
 264	 instructionText: '',
 265	 toastMessage: '',
 266	 showToast: false,
 267	 judgeResult: '',
 268	 scoreValue: ''
 269	 };
 270	 },
 271	 filters: {
 272	 roundPeriodFormatter(val) {
 273	 if (val === 0) {
 274	 return '准备阶段';
 275	 }
 276	 let stageOptions = [
 277	 {title: '直瞄射击阶段'},
 278	 {title: '机动阶段'},
 279	 {title: '解除压制阶段'},
 280	 {title: '间瞄射击阶段'}
 281	 ];
 282	 return stageOptions[val - 1].title;
 283	 }
 284	 },
 285	 mounted() {
 286	 },
 287	 methods: {
 288	 showCustomToast(message) {
 289	 uni.showToast({
 290	 title: message,
 291	 icon: 'none',
 292	 duration: 1500
 293	 });
 294	 },
 295	
 296	 confirmJudge(notJudgeNumber) {
 297	 this.recordMap[this.key][this.index].historyVoList[this.eindex].status = 2;
 298	 if (this.showInfo.userType === 'admin') {
 299	 this.recordMap[this.key][this.index].historyVoList[this.eindex].attackScore = this.scoreValue;
 300	 } else {
 301	 this.recordMap[this.key][this.index].historyVoList[this.eindex].attackResult = this.judgeResult;
 302	 }
 303	 console.log('裁决完毕')
 304	 this.$emit('judgeComplete');
 305	 },
 306	
 307	 confirmJudgeAction() {
 308	 if (!this.judgeResult) {
 309	 this.showCustomToast('请选择裁决结果');
 310	 return;
 311	 }
 312	 this.judge_result = this.judgeResult;
 313	 this.submitJudge();
 314	 },
 315	
 316	 confirmScore() {
 317	 if (!this.scoreValue) {
 318	 this.showCustomToast('请输入评分');
 319	 return;
 320	 }
 321	 this.judge_score = this.scoreValue;
 322	 this.submitJudge();
 323	 },
 324	
 325	 submitJudge() {
 326	 if (this.showInfo.userType === 'admin') {
 327	 this.actionInfo.attackScore = this.judge_score;
 328	 } else {
 329	 this.actionInfo.attackResult = this.judge_result;
 330	 }
 331	
 332	 confirmJudge(this.actionInfo).then((res) => {
 333	 if (res.data.code === 200) {
 334	 this.showCustomToast("提交成功");
 335	 this.confirmJudge(res.data.data);
 336	
 337	 this.judge_result = '';
 338	 this.judge_score = '';
 339	 this.judgeResult = '';
 340	 this.scoreValue = '';
 341	
 342	 setTimeout(() => {
 343	 this.closeJudge();
 344	 }, 1000);
 345	 } else {
 346	 this.showCustomToast(res.data.msg || '提交失败');
 347	 }
 348	 }).catch(err => {
 349	 this.showCustomToast('网络错误，请重试');
 350	 });
 351	 },
 352	
 353	 stepJudge() {
 354	 this.$refs.popup.close();
 355	 this.$emit('stepJudge');
 356	 },
 357	
 358	 judgeOneByOne(eitem, key, index, eindex) {
 359	 this.key = key;
 360	 this.index = index;
 361	 this.eindex = eindex;
 362	 this.actionInfo = eitem;
 363	 if (this.showInfo.userType === 'admin') {
 364	 this.$refs.scorePopup.open();
 365	 } else {
 366	 this.$refs.judgePopup.open();
 367	 }
 368	 },
 369	
 370	 open() {
 371	 this.$refs.popup.open();
 372	 },
 373	
 374	 close() {
 375	 this.$refs.popup.close();
 376	 },
 377	
 378	 closeJudge() {
 379	 this.$refs.judgePopup.close();
 380	 this.$refs.scorePopup.close();
 381	 this.judge_result = '';
 382	 this.judge_score = '';
 383	 this.judgeResult = '';
 384	 this.scoreValue = '';
 385	 },
 386	
 387	 imageClick(url) {
 388	 uni.previewImage({
 389	 urls: [url]
 390	 });
 391	 },
 392	
 393	 async getRoundTree(item) {
 394	 let res = await getHistoryTreeByRound(item);
 395	 let resArray = res.data.data;
 396	 resArray = resArray.filter((item) => {
 397	 item.historyVoList = item.historyVoList.filter((item) => item.actionDesc);
 398	 return item.historyVoList.length > 0;
 399	 });
 400	 if (resArray.length === 0) {
 401	 this.recordMap = {};
 402	 } else {
 403	 this.recordMap = this.groupBy(resArray, 'chessRound');
 404	 }
 405	 },
 406	
 407	 groupBy(arr, key) {
 408	 let obj = {};
 409	 arr.forEach((item) => {
 410	 if (!obj[item[key]]) {
 411	 obj[item[key]] = [];
 412	 }
 413	 obj[item[key]].push(item);
 414	 });
 415	 return obj;
 416	 },
 417	
 418	 deletePic(e) {
 419	 this.fileList.splice(e.index, 1);
 420	 },
 421	
 422	 async afterRead(event) {
 423	 let lists = [].concat(event.file);
 424	 let fileListLen = this.fileList.length;
 425	 lists.map((item) => {
 426	 this.fileList.push({
 427	 ...item,
 428	 status: 'uploading',
 429	 message: '上传中'
 430	 });
 431	 });
 432	
 433	 for (let i = 0; i < lists.length; i++) {
 434	 const result = await this.uploadFilePromise(lists[i].url);
 435	 let item = this.fileList[fileListLen];
 436	 this.fileList.splice(
 437	 fileListLen,
 438	 1,
 439	 Object.assign(item, {
 440	 status: 'success',
 441	 message: '',
 442	 url: result
 443	 })
 444	 );
 445	 fileListLen++;
 446	 }
 447	 },
 448	
 449	 uploadFilePromise(avatarUrl) {
 450	 return new Promise((resolve, reject) => {
 451	 uni.uploadFile({
 452	 url: baseURL + 'system/upload',
 453	 filePath: avatarUrl,
 454	 name: 'file',
 455	 header: {
 456	 Authorization: getUserTokenStorage()
 457	 },
 458	 success: (uploadFileRes) => {
 459	 let jsonRes = JSON.parse(uploadFileRes.data);
 460	 setTimeout(() => {
 461	 resolve(jsonRes.data.url);
 462	 }, 1000);
 463	 },
 464	 fail: (error) => {
 465	 reject(error);
 466	 }
 467	 });
 468	 });
 469	 },
 470	
 471	 async submitInstruct() {
 472	 if ((!this.instructionText || !this.instructionText.trim()) && this.fileList.length === 0) {
 473	 return this.showCustomToast('请至少上传图片或输入文本');
 474	 }
 475	
 476	 let textSaved = false;
 477	 let imageSaved = false;
 478	 let hasError = false;
 479	
 480	 if (this.instructionText && this.instructionText.trim()) {
 481	 this.showInfo.textIns = this.instructionText;
 482	 try {
 483	 let resText = await saveTextInstruction(this.showInfo);
 484	 if (resText.data && resText.data.code === 200) {
 485	 textSaved = true;
 486	 } else {
 487	 hasError = true;
 488	 }
 489	 } catch (error) {
 490	 hasError = true;
 491	 }
 492	 }
 493	
 494	 if (this.fileList.length !== 0) {
 495	 this.showInfo.coverUrl = this.fileList[0].url;
 496	 try {
 497	 let resCover = await saveRoundCover(this.showInfo);
 498	 if (resCover.data && resCover.data.code === 200) {
 499	 imageSaved = true;
 500	 } else {
 501	 hasError = true;
 502	 }
 503	 } catch (error) {
 504	 hasError = true;
 505	 }
 506	 }
 507	
 508	 if (hasError) {
 509	 this.showCustomToast('保存失败');
 510	 } else if (textSaved || imageSaved) {
 511	 this.showCustomToast('保存成功');
 512	 this.fileList = [];
 513	 this.instructionText = '';
 514	 this.$refs.popup.close();
 515	 }
 516	 }
 517	 }
 518	};
 519	</script>
 520	
